 cost=dict(total_Source_captures_completed=0,final_worker_DINO_encodings_completed=0,engineering_DINO_encodings_completed=0,new_training_runs=0,new_heads=0,new_GPU_seconds=read(D/'GPU_COST_RECEIPT.json')['GPU_allocation_seconds'],fit_episodes=96,round_slots=192,actual_informative_steps=sum(f['informative_steps']for r in z['rows']for f in r['fits'].values()),actual_unique_trajectory_decoder_calls=sum(r['compute']['actual_decoder_trajectory_calls']for r in z['rows']),actual_PosDecoder_calls=sum(r['compute']['actual_PosDecoder_calls']for r in z['rows']),backward_calls=0,old_Source_E_DINO_replay_inputs_cost_excluded=True,not_first_online_latency=True)
