  ax.axhline(0,color='k',lw=.7);ax.set_xticks(range(4),['Fixed','Live','Shuffle','Mean']);ax.set(title=ds,ylabel='Complete vIoU change vs E (pp)');ax.ticklabel_format(axis='y',style='sci',scilimits=(0,0))
